  var pats = [
    new RegExp(esc + "\\s*[:=]\\s*\\{?\\[?\\(?\\s*([A-Za-zÀ-ÿ0-9][^\\n.;]{2,160})", 'i'),
    // tolère quelques mots entre le champ et le ':' (ex: "statut d une commande : a, b, c")
    new RegExp(esc + "(?:\\s+[a-zà-ÿ'’]+){1,4}\\s*[:=]\\s*([A-Za-zÀ-ÿ0-9][^\\n.;]{2,160})", 'i'),
