    new RegExp(esc + "[^\\n]{0,50}?(?:peut[\\s\\S]{0,14}?(?:être|etre)|parmi|valeurs?|choix|options?)\\s*[:=]?\\s*([A-Za-zÀ-ÿ0-9][^\\n.;]{2,160})", 'i')
  ];
