    var m = spec.match(pats[i]);
    if(m && m[1]){
      var parts = m[1].split(/\s*(?:,|\/|\||;|•|\bou\b|\bor\b|\bet\b|\band\b)\s*/i)
        .map(function(s){ return s.trim().replace(/^["'`«»\-\s]+/,'').replace(/["'`«».\s]+$/,'').trim(); })
